-- Authority publication is distinct from mail metadata/content and legacy
-- settings_revision. These small tables and DML triggers do not backfill data.
-- Clock/activity touches are observed fresh, not versioned. No-op ciphertext
-- rewrites may conservatively dirty a scoped epoch; ciphertext is not decoded here.
CREATE TABLE authority_epoch (
 scope_kind TEXT NOT NULL CHECK(scope_kind IN ('policy','routing','directory','protection','domain','account','principal','session','watch','subject')),
 scope_id TEXT NOT NULL CHECK(typeof(scope_id)='text' AND octet_length(scope_id)<=4096),
 incarnation TEXT NOT NULL DEFAULT(lower(hex(randomblob(16)))) CHECK(octet_length(incarnation)=32 AND incarnation NOT GLOB '*[^0-9a-f]*'),
 version BIGINT NOT NULL DEFAULT 1 CHECK(typeof(version)='integer' AND version>0),
 PRIMARY KEY(scope_kind,scope_id)
);
CREATE TABLE authority_publication_outbox (
 scope_kind TEXT NOT NULL,
 scope_id TEXT NOT NULL,
 incarnation TEXT NOT NULL,
 target_version BIGINT NOT NULL CHECK(typeof(target_version)='integer' AND target_version>0),
 notified_version BIGINT NOT NULL DEFAULT 0 CHECK(typeof(notified_version)='integer' AND notified_version>=0 AND notified_version<=target_version),
 claim_token TEXT,
 claim_until BIGINT,
 PRIMARY KEY(scope_kind,scope_id),
 FOREIGN KEY(scope_kind,scope_id) REFERENCES authority_epoch(scope_kind,scope_id) ON DELETE CASCADE
);
CREATE TRIGGER authority_epoch_monotonic BEFORE UPDATE ON authority_epoch
WHEN NEW.scope_kind IS NOT OLD.scope_kind OR NEW.scope_id IS NOT OLD.scope_id OR NEW.incarnation IS NOT OLD.incarnation OR NEW.version<=OLD.version
BEGIN SELECT RAISE(ABORT,'authority epoch cannot reset or change incarnation'); END;
CREATE TRIGGER authority_epoch_outbox_insert AFTER INSERT ON authority_epoch BEGIN
 INSERT INTO authority_publication_outbox(scope_kind,scope_id,incarnation,target_version) VALUES(NEW.scope_kind,NEW.scope_id,NEW.incarnation,NEW.version)
 ON CONFLICT(scope_kind,scope_id) DO UPDATE SET incarnation=excluded.incarnation,target_version=excluded.target_version,
 notified_version=CASE WHEN authority_publication_outbox.incarnation=excluded.incarnation THEN authority_publication_outbox.notified_version ELSE 0 END,
 claim_token=NULL,claim_until=NULL;
END;
CREATE TRIGGER authority_epoch_outbox_update AFTER UPDATE ON authority_epoch BEGIN
 INSERT INTO authority_publication_outbox(scope_kind,scope_id,incarnation,target_version) VALUES(NEW.scope_kind,NEW.scope_id,NEW.incarnation,NEW.version)
 ON CONFLICT(scope_kind,scope_id) DO UPDATE SET incarnation=excluded.incarnation,target_version=excluded.target_version,
 notified_version=CASE WHEN authority_publication_outbox.incarnation=excluded.incarnation THEN authority_publication_outbox.notified_version ELSE 0 END,
 claim_token=NULL,claim_until=NULL;
END;
CREATE TRIGGER authority_setting_policy_insert AFTER INSERT ON setting_policy BEGIN
 INSERT INTO authority_epoch(scope_kind,scope_id) SELECT 'policy','' WHERE CASE WHEN typeof('')<>'text' OR octet_length('')>4096 THEN 0 WHEN instr(CAST('' AS BLOB),X'00') OR '' GLOB '*[^ -~]*' THEN 0 WHEN ''='' AND 'policy' NOT IN ('policy','routing','directory','protection') THEN 0 ELSE 1 END ON CONFLICT(scope_kind,scope_id) DO UPDATE SET version=authority_epoch.version+1;
END;
CREATE TRIGGER authority_setting_policy_update AFTER UPDATE ON setting_policy BEGIN
 INSERT INTO authority_epoch(scope_kind,scope_id) SELECT 'policy','' WHERE CASE WHEN typeof('')<>'text' OR octet_length('')>4096 THEN 0 WHEN instr(CAST('' AS BLOB),X'00') OR '' GLOB '*[^ -~]*' THEN 0 WHEN ''='' AND 'policy' NOT IN ('policy','routing','directory','protection') THEN 0 ELSE 1 END ON CONFLICT(scope_kind,scope_id) DO UPDATE SET version=authority_epoch.version+1;
