CREATE TRIGGER authority_setting_value_insert AFTER INSERT ON setting_value BEGIN
 INSERT INTO authority_epoch(scope_kind,scope_id) SELECT CASE WHEN NEW.scope_kind='domain' THEN 'domain' WHEN NEW.scope_kind IN ('user','admin_user') THEN 'subject' ELSE 'policy' END,CASE WHEN NEW.scope_kind IN ('domain','user','admin_user') THEN NEW.scope_id ELSE '' END WHERE CASE WHEN typeof(CASE WHEN NEW.scope_kind IN ('domain','user','admin_user') THEN NEW.scope_id ELSE '' END)<>'text' OR octet_length(CASE WHEN NEW.scope_kind IN ('domain','user','admin_user') THEN NEW.scope_id ELSE '' END)>4096 THEN 0 WHEN instr(CAST(CASE WHEN NEW.scope_kind IN ('domain','user','admin_user') THEN NEW.scope_id ELSE '' END AS BLOB),X'00') OR CASE WHEN NEW.scope_kind IN ('domain','user','admin_user') THEN NEW.scope_id ELSE '' END GLOB '*[^ -~]*' THEN 0 WHEN CASE WHEN NEW.scope_kind IN ('domain','user','admin_user') THEN NEW.scope_id ELSE '' END='' AND (CASE WHEN NEW.scope_kind='domain' THEN 'domain' WHEN NEW.scope_kind IN ('user','admin_user') THEN 'subject' ELSE 'policy' END) NOT IN ('policy','routing','directory','protection') THEN 0 ELSE 1 END ON CONFLICT(scope_kind,scope_id) DO UPDATE SET version=authority_epoch.version+1;
END;
